#include "bite.h"
#include "body.h"
#include "pose.h"
#include "../flow/phase_controller.h"
#include <algorithm>
namespace speed {
void DracoBite::begin(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);v.move=DracoBiteState{};auto &s=std::get<DracoBiteState>(v.move);auto &b=*PhaseController::find(r,t.actor);auto &e=r.state.enemies[t.actor.slot];const auto &p=r.content->boss_techniques[t.definition-1];const auto &d=*std::find_if(r.content->draco_bites.begin(),r.content->draco_bites.end(),[&](const auto &d){return d.technique==t.definition;});s.origin=e.pos;t.aim=DracoTechnique::predict(r,t.actor,p.warn+p.active*0.55,d.lead_cap);t.direction=(t.aim-s.origin).normalized();if (t.direction.is_zero_approx()) t.direction=godot::Vector2(1,0);e.facing=t.direction.angle();s.base=DracoTechnique::neutral(r,b,s.origin,e.facing);s.retracted=s.origin-t.direction*d.retract;s.strike=s.origin+t.direction*p.reach;v.warning={s.origin,s.strike+t.direction*105*b.draco.head_scale};v.warning_width=p.width;}
void DracoBite::windup(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);const auto &s=std::get<DracoBiteState>(v.move);DracoTechnique::neck(r,*PhaseController::find(r,t.actor),s.base,s.origin.lerp(s.retracted,DracoTechnique::smooth(v.stage_time/std::max(0.001,r.content->boss_techniques[t.definition-1].warn))));}
void DracoBite::active(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);const auto &s=std::get<DracoBiteState>(v.move);auto &b=*PhaseController::find(r,t.actor);v.warning.clear();const auto before=DracoTechnique::mouth(r,b);DracoTechnique::neck(r,b,s.base,s.retracted.lerp(s.strike,DracoTechnique::smooth(v.stage_time/std::max(0.001,r.content->boss_techniques[t.definition-1].active))));const auto after=DracoTechnique::mouth(r,b);v.attack={before,after};DracoTechnique::hit_segment(r,t,before,after,r.content->boss_techniques[t.definition-1].width);}
void DracoBite::end(RunRuntime &r,TechniqueState &t,bool cancelled) {auto &v=std::get<DracoTechniqueState>(t.detail);auto &s=std::get<DracoBiteState>(v.move);v.warning.clear();v.attack.clear();auto *b=PhaseController::find(r,t.actor);if (!b) return;s.landed=b->draco.override_points;if (cancelled && r.state.enemy_handles.contains(t.actor)) {r.state.enemies[t.actor.slot].pos=s.origin;DracoPose::reset(r,*b);}}
void DracoBite::recover(RunRuntime &r,TechniqueState &t) {const auto &v=std::get<DracoTechniqueState>(t.detail);const auto &s=std::get<DracoBiteState>(v.move);if (s.landed.empty()) return;auto &b=*PhaseController::find(r,t.actor);DracoTechnique::blend(r,b,s.landed,DracoTechnique::neutral(r,b,s.origin,t.direction.angle()),v.stage_time/std::max(0.001,r.content->boss_techniques[t.definition-1].recover));}
bool DracoBite::validate(const DracoBiteState &s) {if (!s.origin.is_finite() || !s.retracted.is_finite() || !s.strike.is_finite() || s.base.size()<2) return false;for (const auto *points:{&s.base,&s.landed}) for (auto p:*points) if (!p.is_finite()) return false;return true;}
}
